import{_ as i,o as a,c as t,a2 as n}from"./chunks/framework.BEUshCVJ.js";const u=JSON.parse('{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"reference/changelog.md","filePath":"reference/changelog.md","lastUpdated":1792881664000}'),o={name:"reference/changelog.md"};function r(s,e,l,d,h,c){return a(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><p>All notable changes to MeetCue. Versions follow <a href="https://semver.org/" target="_blank" rel="noreferrer">Semantic Versioning</a>.</p><h2 id="_0-1-3-—-2026-10-24" tabindex="-1">0.1.3 — 2026-10-24 <a class="header-anchor" href="#_0-1-3-—-2026-10-24" aria-label="Permalink to &quot;0.1.3 — 2026-10-24&quot;">​</a></h2><h3 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Prices are read live from Anthropic&#39;s, Soniox&#39;s and Deepgram&#39;s official pricing pages, and from OpenAI-compatible servers that list prices with their models. Every current Claude model now shows its price and estimated cost; only a model with no price anywhere links to the pricing page.</li><li>Deepgram shows the rate billed today, including limited-time promotions, with the regular rate in the tooltip.</li><li>Changing a model, key, language or hint setting during a meeting takes effect right away: the next question uses the new models, and recognition switches without losing the sentence in progress.</li></ul><h3 id="added" tabindex="-1">Added <a class="header-anchor" href="#added" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>Settings › Diagnostics › Activity log</strong> shows what MeetCue is doing as it happens: starting and pausing, whether audio arrives from each side, recognised sentences, questions and errors. Also in the tray menu, and from any error message.</li></ul><h3 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Clicking <strong>Start</strong> or <strong>Resume</strong> when something was missing (a key, a model, the audio device) did nothing; the reason is now shown, and a session whose audio fails to start is no longer left half running.</li><li>Notices such as a shortcut that&#39;s already taken were never shown.</li><li>The meeting clock kept counting while paused.</li><li>The settings tab list scrolled away on long pages.</li><li>Speech recognition: <ul><li>The first sound of a sentence was often cut off; the 0.3 s before speech is now sent with it.</li><li>Recognition stopped for the rest of the meeting after a second connection drop, and after pausing for more than a few seconds; it now keeps the connection alive while paused and reconnects whenever needed.</li><li>With Deepgram, English sentences lost the spaces between their parts (&quot;yourexperience&quot;).</li><li>With Deepgram and both Chinese and English selected, English was sent to the Mandarin model. The first language in <strong>Meeting languages</strong> is now the main one, and there is a &quot;Mostly English, some Chinese&quot; choice.</li><li>The end-of-sentence silence setting was cut short at 0.8 s.</li></ul></li></ul><h2 id="_0-1-2-—-2026-10-24" tabindex="-1">0.1.2 — 2026-10-24 <a class="header-anchor" href="#_0-1-2-—-2026-10-24" aria-label="Permalink to &quot;0.1.2 — 2026-10-24&quot;">​</a></h2><h3 id="changed-1" tabindex="-1">Changed <a class="header-anchor" href="#changed-1" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Prices are no longer built into the app. MeetCue downloads the <a href="/meetcue/reference/pricing">price reference</a>, checked against each provider&#39;s official pricing page, keeps the last copy for offline use, and can update it from <strong>Settings › Providers &amp; cost</strong>.</li><li>A more compact <strong>Models &amp; prices</strong> layout: one line per model with its price and estimated cost per hour, sorted by cost, with <strong>Cheapest</strong> and <strong>Fastest</strong> marked. API keys take one row per provider.</li><li>A model without a published price links to the provider&#39;s official pricing page instead of showing <strong>Price unknown</strong>.</li></ul><h3 id="fixed-1" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-1" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Deepgram Nova-3 used the multilingual rate. MeetCue requests one language for Chinese or English, which costs $0.0077 per minute.</li></ul><h3 id="added-1" tabindex="-1">Added <a class="header-anchor" href="#added-1" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Prices for Claude Sonnet 5, Claude Opus 5 and Claude Fable 5.1.</li></ul><h2 id="_0-1-1-—-2026-10-24" tabindex="-1">0.1.1 — 2026-10-24 <a class="header-anchor" href="#_0-1-1-—-2026-10-24" aria-label="Permalink to &quot;0.1.1 — 2026-10-24&quot;">​</a></h2><h3 id="fixed-2" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-2" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Deepgram, Anthropic and OpenAI-compatible keys failed verification and sessions using them would not start: only Soniox was wired up.</li><li>The setup window turned blank instead of closing when you clicked <strong>Finish</strong>.</li><li>Switches in Settings were drawn with the knob off-centre.</li></ul><h3 id="removed" tabindex="-1">Removed <a class="header-anchor" href="#removed" aria-label="Permalink to &quot;Removed&quot;">​</a></h3><ul><li>Amazon Bedrock. Use Anthropic or an OpenAI-compatible API for hints.</li></ul><h2 id="_0-1-0-—-2026-10-23" tabindex="-1">0.1.0 — 2026-10-23 <a class="header-anchor" href="#_0-1-0-—-2026-10-23" aria-label="Permalink to &quot;0.1.0 — 2026-10-23&quot;">​</a></h2><h3 id="added-2" tabindex="-1">Added <a class="header-anchor" href="#added-2" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Meeting mode: live question detection with early trigger, numbered talking points in about a second and a half, a question queue, and coverage ticks.</li><li>Floating panel that doesn&#39;t take focus, with full and mini layouts, click-through and hiding from screen sharing.</li><li>Speech recognition with Soniox and Deepgram; hints with Anthropic, Amazon Bedrock and OpenAI-compatible APIs.</li><li>Latency probe with endpoint selection, cost estimates and combination ranking.</li><li>Price table, usage tracking, budgets and CSV export.</li><li>Practice mode: subtitle and question-list import with preview editing, questions read aloud with system voices, real or simulated recognition, follow-up questions, four hint levels, and a review report with Markdown export.</li><li>Briefing material from txt, md, docx and pdf files.</li><li>English and Simplified Chinese interface and documentation.</li><li>Error codes with linked fixes, diagnostics export, <code>--demo</code> and <code>--self-test</code>.</li></ul>',24)])])}const p=i(o,[["render",r]]);export{u as __pageData,p as default};
